public class PedidosController : ControllerBase
{
    private readonly IRepositorioPedido _repo;
    public PedidosController(IRepositorioPedido repo) => _repo = repo;

    [HttpGet("caros")]
    public IActionResult ListarCaros()
        => Ok(_repo.ListarTodos().Where(p => p.Total > 100));
}

