public record Cliente(int Id, string Nome, string? Email);

public interface IRepositorioCliente
{
    IEnumerable<Cliente> ListarTodos();
    Cliente? BuscarPorId(int id);
}

public async Task<Cliente?> BuscarClienteAsync(int id)
{
    await Task.Delay(50); // simula chamada assíncrona ao banco
    return _repositorio.ListarTodos().FirstOrDefault(c => c.Id == id);
}

[HttpGet("{id}")]
public async Task<IActionResult> ObterCliente(int id)
{
    Cliente? cliente = await _servico.BuscarClienteAsync(id);
    return cliente is null ? NotFound() : Ok(cliente);
}

